import {createNextUI} from './next-ui.js';
import {renderMarkdown} from './markdown.js';
const app=document.getElementById('app'),dialog=document.getElementById('dialog'),dialogContent=document.getElementById('dialog-content'),token=document.querySelector('meta[name=workbench-token]').content;
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={active:'使用中',completed:'已完成',pending_delete:'待刪除',keep:'保留',candidate:'候選',validated:'已確認',needs_review:'需複核',rejected:'不採用',archived:'已封存',trashed:'回收區',open:'待核對',accepted:'已採用',dismissed:'已忽略',snoozed:'延後',resolved:'已處理',stale:'來源已變',proposed:'提案',applied:'已套用',restored:'已還原',recovery_required:'需修復',failed:'失敗',cancelled:'已取消',passed:'通過',unverified:'未驗證',pending:'待檢查',partial:'部分完成',queued:'排隊中',running:'處理中'};
const types={preference:'偏好',fact:'事實',decision:'決策',method:'方法',failure:'失敗案例',gotcha:'陷阱'};
const badge=(text,kind='')=>`<span class="badge ${kind}">${e(names[text]||text)}</span>`;
const options=(items,value)=>items.map(x=>{const [v,label]=Array.isArray(x)?x:[x,names[x]||x];return `<option value="${e(v)}" ${v===value?'selected':''}>${e(label)}</option>`;}).join('');
const empty=(text='沒有符合條件的資料')=>`<div class="empty">${e(text)}</div>`;
let state,mode='md',page='files',data={},selected=null,selectedKnowledge=null,task=null,docTab='note',seq=0,filePage=1,pageSize=50,job=null,jobTimer,toastTimer,searchTimer;
let taskCursor='',historyOffset=0,historyQuery='',selectionSnapshot=null;
const snapshotExcluded=new Set(),snapshotPageIds=new Set(),cursorStacks={findings:[],knowledge:[],tasks:[],domains:[]};
function selectionCount(){return selectionSnapshot?selectionSnapshot.total-snapshotExcluded.size:checked.size;}
function isSelected(id){return selectionSnapshot?snapshotPageIds.has(id)&&!snapshotExcluded.has(id):checked.has(id);}
function cursorBack(kind){return '<div class="row page-top"><button data-action="cursor-first" data-kind="'+kind+'">第一頁</button><button data-action="cursor-back" data-kind="'+kind+'" '+(!cursorStacks[kind].length?'disabled':'')+'>上一頁</button></div>';}
function viewState(){const focus=document.activeElement;return {key:page+':'+(selected?.id||''),focus:focus?.matches('input,textarea,select')?{id:focus.id,name:focus.name,context:focus.closest('form')?.dataset.context,select:focus.dataset.select,start:focus.selectionStart,end:focus.selectionEnd}:null,scroll:[...app.querySelectorAll('.workspace>.panel')].map(x=>x.scrollTop)};}
function restoreView(v){if(v.key!==page+':'+(selected?.id||''))return;[...app.querySelectorAll('.workspace>.panel')].forEach((x,i)=>{x.scrollTop=v.scroll[i]||0;});if(!v.focus)return;let el=v.focus.id?document.getElementById(v.focus.id):[...app.querySelectorAll('form')].find(f=>f.dataset.context===v.focus.context)?.elements.namedItem(v.focus.name);if(v.focus.select)el=[...app.querySelectorAll('[data-select]')].find(x=>x.dataset.select===v.focus.select);el?.focus({preventScroll:true});if(el?.setSelectionRange&&typeof v.focus.start==='number')try{el.setSelectionRange(v.focus.start,v.focus.end);}catch{};}

let editingDomain=null,domainCursor='';
let filter={rootId:'',query:'',status:'',category:'',cursor:''},knowledgeFilter={query:'',review:'',lifecycle:'active',cursor:''},findingFilter={state:'open',rule:'',cursor:''};
const checked=new Map(),drafts=new Map(),imageUrls=new Map();
const formStates=new Map();
function captureForms(){for(const form of app.querySelectorAll('form[data-context]')){const fields=[...form.elements].filter(el=>el.name).map(el=>({name:el.name,type:el.type,value:el.type==='checkbox'?el.checked:el.value}));formStates.set(form.dataset.context,fields);}while(formStates.size>30)formStates.delete(formStates.keys().next().value);}
function restoreForms(){for(const form of app.querySelectorAll('form[data-form]')){const type=form.dataset.form,context=type==='criterion'?`${type}:${task?.id}:${task?.revision}:${form.dataset.id}`:selected?`${type}:${selected.id}:${selected.hash}:${selected.mark?.at||''}`:`${type}:${page}:${filter.rootId}`;form.dataset.context=context;for(const field of formStates.get(context)||[]){const el=form.elements.namedItem(field.name);if(!el)continue;if(field.type==='checkbox')el.checked=field.value;else if(!(el.tagName==='SELECT'&&field.value===''&&![...el.options].some(o=>o.value==='')))el.value=field.value;}}}
async function api(url,input){const res=await fetch(url,{method:input===undefined?'GET':'POST',headers:{'x-workbench-token':token,...(input===undefined?{}:{'content-type':'application/json'})},...(input===undefined?{}:{body:JSON.stringify(input)})});const out=await res.json().catch(()=>{throw new Error('服務回應不完整，請重新整理後再試');});if(!res.ok)throw new Error(out.error||'操作失敗');return out.result??out;}
const call=(name,args={})=>api('/api/call',{name,arguments:args});
const nextUI=createNextUI({api,call,e,toast,openDialog,closeDialog,state:()=>state,task:()=>task,scope:()=>filter.rootId,document:()=>selected,selection:()=>[...checked.values()],showPlan:(id,kind)=>planDialog(id,kind||'plan'),reload:()=>loadView()});
function toast(text,kind='success'){
  clearTimeout(toastTimer);if(kind!=='loading')api('/api/activity',{action:'add',title:String(text).slice(0,2000),status:kind,scope:filter.rootId||'personal'}).catch(()=>{});const node=document.getElementById('toast');node.dataset.kind=kind;
  node.innerHTML=`<span>${e(kind==='error'?'操作未完成：':kind==='loading'?'處理中：':'')}${e(text)}</span><button data-action="dismiss-feedback" aria-label="關閉操作提示">×</button>`;
  const local=document.getElementById('dialog-status');if(local){local.dataset.kind=kind;local.textContent=kind==='error'?`操作未完成：${text}`:text;}
  if(kind==='success')toastTimer=setTimeout(()=>{node.replaceChildren();if(local?.isConnected)local.textContent='';},8000);
}
let busy=false;
async function runUi(work,trigger){
  if(busy){toast('上一項操作仍在處理，請稍候','loading');return;}
  busy=true;const wasDisabled=trigger?.disabled;if(trigger){trigger.disabled=true;trigger.setAttribute('aria-busy','true');}
  document.body.setAttribute('aria-busy','true');
  try{await work();}catch(err){toast(err.message,'error');}
  finally{busy=false;document.body.removeAttribute('aria-busy');if(trigger){trigger.disabled=wasDisabled;trigger.removeAttribute('aria-busy');}}
}
async function perform(work){try{await work();}catch(err){toast(err.message,'error');}}
function openDialog(title,body,foot=''){if(document.getElementById('toast').dataset.kind==='loading')document.getElementById('toast').replaceChildren();dialogContent.innerHTML=`<div class="dialog-head"><h2>${e(title)}</h2><button data-action="close" aria-label="關閉">×</button></div><div id="dialog-status" role="status" aria-live="polite"></div><div class="dialog-body">${body}</div><div class="dialog-foot"><button data-action="close">關閉</button>${foot}</div>`;if(!dialog.open)dialog.showModal();}
function closeDialog(){dialog.close();dialogContent.replaceChildren();if(document.getElementById('toast').dataset.kind==='loading')document.getElementById('toast').replaceChildren();}
dialog.addEventListener('close',()=>{if(!dialog.open)dialogContent.replaceChildren();});
function rootOptions(value='',personal=false){return options([...(personal?[['personal','個人範圍']]:[['','所有已加入範圍']]),...state.roots.map(r=>[r.id,r.name])],value);}
async function refresh(){state=await api('/api/state');if(state.role==='insight'&&mode!=='insight'){mode='insight';page='tasks';}if(state.role==='md')mode='md';await loadView();}
async function loadView(){const request=++seq;let result,nextTask;
  if(nextUI.owns(page))result=await nextUI.load(page);
  if(page==='files'){result=await call('list_documents',{...filter,cursor:'',offset:(filePage-1)*pageSize,limit:pageSize});const last=Math.max(1,Math.ceil(result.total/pageSize));if(filePage>last){filePage=last;return loadView();}}
  if(page==='findings')result=await call('audit_markdown',{...findingFilter,rootId:filter.rootId||undefined});
  if(page==='history'||page==='trash')result=await api('/api/history',{paged:true,offset:historyOffset,limit:30,query:historyQuery});
  if(page==='knowledge')result=await call('list_knowledge',{...knowledgeFilter,scope:filter.rootId||undefined,limit:30});
  if(page==='tasks'){result=await call('list_task_briefs',{scope:filter.rootId||undefined,cursor:taskCursor||undefined});if(task)nextTask=await call('resolve_task_brief',{id:task.id});}
  if(page==='domains')result=await api('/api/domains',{scope:filter.rootId||undefined,cursor:domainCursor||undefined});
  if(page==='visual')result=await call('list_visual_references',{scope:filter.rootId||undefined,offset:nextUI.getVisualOffset(),limit:24});
  if(page==='report')result=task?await call('build_learning_report',{taskId:task.id}):null;
  if(page==='scopes')result=state.roots;
  if(page==='files'&&selectionSnapshot){const membership=await call('selection_snapshot',{action:'membership',id:selectionSnapshot.id,documentIds:(result.documents||[]).map(d=>d.id)});snapshotPageIds.clear();for(const id of membership.ids)snapshotPageIds.add(id);}
  if(request!==seq)return;if(nextTask)task=nextTask;data=result||{};render();}
function navigation(){const items=mode==='md'?[['files','文件工作區'],['findings','整理待核對'],['history','變更批次'],['trash','回收與修復']]:[['tasks','本次任務'],['knowledge','知識與經驗'],['domains','領域來源'],['report','成果回報'],['visual','視覺參考'],['history','維護批次']];items.push(...nextUI.nav.filter(([id])=>mode==='insight'||['policies','drafts','activity'].includes(id)));items.push(['scopes','管理範圍']);return items.map(([id,label])=>`<button data-action="navigate" data-page="${id}" class="${page===id?'active':''}">${label}</button>`).join('');}
function render(){const previousView=viewState();captureForms();const title={files:'文件工作區',findings:'整理待核對',history:'變更批次',trash:'回收與修復',tasks:'需求先對齊，再選擇方法',knowledge:'按任務取用知識',domains:'領域來源與適用版本',report:'成果有證據，缺口可追蹤',visual:'視覺參考與比較',scopes:'管理範圍',context:'這次工作需要的脈絡',sources:'研究資料庫',policies:'自主整理的授權範圍',drafts:'未寫入原文件的草稿',activity:'操作結果與問題',evaluations:'成果與成本對照'}[page];
  app.innerHTML=`<div class="shell ${mode==='insight'?'insight':''} "><header class="top"><div class="brand"><span class="logo">${mode==='md'?'M':'I'}</span><div><strong>${mode==='md'?'MD 管理台':'理解工作台'}</strong><small>WORKBENCH · v${e(state.overview.version)}</small></div></div>${state.role==='both'?`<div class="switch"><button data-action="mode" data-mode="md" class="${mode==='md'?'active':''}">MD 管理台</button><button data-action="mode" data-mode="insight" class="${mode==='insight'?'active':''}">理解工作台</button></div>`:''}<select id="root-scope" class="top-scope" aria-label="目前管理範圍">${rootOptions(filter.rootId)}</select></header><div class="layout"><aside class="sidebar"><nav class="nav" aria-label="工作區">${navigation()}</nav><div class="side-foot">${state.overview.documents} 份文件 · ${state.overview.memories} 筆經驗<br>本機資料 · 按需取用<br><button class="small" data-action="refresh" style="margin-top:10px">重新整理</button></div></aside><main class="main"><div class="heading"><div><h1>${title}</h1><p>${mode==='md'?'檢查變更、來源與影響，再套用整理方案。':'保留目的、適用情境與證據，先摘要再詳讀。'}</p></div><div class="row">${mode==='md'?'<button data-action="new-scope">加入範圍</button><button class="primary" data-action="scan">索引新增與變更</button>':'<button data-action="new-task">新增任務</button><button class="primary" data-action="new-knowledge">新增經驗</button>'}</div></div>${job?jobBar():''}${renderPage()}<div class="status-line">${state.overview.latestScan?`最近索引：${e(new Date(state.overview.latestScan.at).toLocaleString())} · ${badge(state.overview.latestScan.status||'完成')}`:'尚未索引來源。'} · 原始文件保留於加入的資料夾。</div></main></div></div>`;restoreForms();nextUI.restoreDrafts();hydrateImages();restoreView(previousView);const pageBox=document.getElementById('select-page');if(pageBox){const docs=data.documents||[],n=docs.filter(d=>isSelected(d.id)).length;pageBox.indeterminate=n>0&&n<docs.length;}}
function renderPage(){if(nextUI.owns(page))return nextUI.render(page,data);switch(page){case'files':return filesPage();case'findings':return findingsPage()+cursorBack('findings');case'history':case'trash':return historyPage();case'knowledge':return knowledgePage()+cursorBack('knowledge');case'tasks':return tasksPage()+cursorBack('tasks')+`<div class="list-footer"><span>每頁10筆任務摘要</span><div class="row"><button data-action="first-task-page">第一頁</button><button data-action="next-task-page" ${data.nextCursor?'':'disabled'}>下一頁</button></div></div>`;case'domains':return domainsPage()+cursorBack('domains')+`<div class="list-footer"><span>每頁10筆來源摘要</span><div class="row"><button data-action="first-domains">第一頁</button><button data-action="next-domains" ${data.nextCursor?'':'disabled'}>下一頁</button></div></div>`;case'report':return reportPage();case'visual':return visualPage()+nextUI.visualExtra(data);case'scopes':return scopesPage();}}
function jobBar(){const html=jobBarBase(),at=html.lastIndexOf('</div>');return html.slice(0,at)+(job?.errors?.length?'<details><summary>查看 '+(job.failed||job.errors.length)+' 項未完成項目</summary>'+job.errors.map(item=>'<p class="mono">'+e(item.id)+': '+e(item.error)+'</p>').join('')+'</details>':'')+html.slice(at);}
function jobBarBase(){return `<div class="jobbar"><div class="row space"><span>索引工作：${e(names[job.status]||job.status)} · 已檢查 ${job.processed||job.result?.count||0} 份 · 變更 ${job.changed||job.result?.changed||0} 份${job.result?` · 重讀 ${job.result.readFiles} 份` :''}${job.error?` · ${e(job.error)}`:''}</span>${['running','queued'].includes(job.status)?`<button class="small" data-action="cancel-job">取消工作</button>`:''}</div>${job.result?.warnings?.length?`<details><summary>查看 ${job.result.warnings.length} 項索引問題</summary>${job.result.warnings.map(w=>`<p class="mono">${e(w.path)}<br>${e(w.reason)}</p>`).join('')}</details>`:''}</div>`;}
function filesPage(){
  const docs=data.documents||[],pages=Math.max(1,Math.ceil((data.total||0)/pageSize)),pageChecked=docs.filter(d=>isSelected(d.id)).length;
  const controls=`<div class="pagination row" aria-label="文件分頁"><button class="small" data-action="first-page" ${filePage===1?'disabled':''}>第一頁</button><button class="small" data-action="previous-page" ${filePage===1?'disabled':''}>上一頁</button><span>第 ${filePage}／${pages} 頁</span><button class="small" data-action="next-page" ${filePage>=pages?'disabled':''}>下一頁</button><button class="small" data-action="last-page" ${filePage>=pages?'disabled':''}>末頁</button><form data-form="jump-page" class="row"><label>前往 <input name="page" type="number" min="1" max="${pages}" value="${filePage}" aria-label="前往頁碼" required></label><button class="small">跳頁</button></form></div>`;
  return `<div class="workspace"><section class="panel"><div class="panel-head"><h2>文件清單 <span class="muted">${data.total||0} 份</span></h2><button class="small" data-action="new-document" ${state.roots.length?'':'disabled'} title="先加入管理範圍，再新增文件">新增文件</button></div><div class="toolbar"><input type="search" id="document-search" aria-label="搜尋文件" placeholder="搜尋名稱或路徑" value="${e(filter.query)}"><select id="status-filter" aria-label="文件狀態">${options([['','所有狀態'],'active','completed','pending_delete','keep'],filter.status)}</select><label class="page-size">每頁 <select id="page-size" aria-label="每頁文件筆數">${options([[50,'50 份'],[100,'100 份'],[200,'200 份']],pageSize)}</select></label><button class="small" data-action="reset-file-filter" ${filter.query||filter.status?'':'disabled'}>重設篩選</button></div><div class="selection-tools row"><label class="check"><input type="checkbox" id="select-page" ${docs.length&&pageChecked===docs.length?'checked':''} ${docs.length?'':'disabled'}>選取本頁 ${docs.length} 份</label><button class="small" data-action="select-filtered" ${!data.total?'disabled':''} title="只選取目前搜尋與狀態篩選的結果，最多 50,000 份；大型選取以快照分批處理">選取全部搜尋結果（${data.total||0} 份）</button><button class="small" data-action="invert-page" ${docs.length?'':'disabled'}>反向選取本頁</button></div>${data.total>2000?'<p class="help selection-help">大型結果會建立選取快照，分段標記並逐份核對來源版本。</p>':''}${selectionCount()?`<div class="batchbar"><span>已選 ${selectionCount()} 份 · 本頁 ${pageChecked} 份 · 含其他頁與篩選</span><div class="row"><button class="small" data-action="merge" ${selectionCount()<2||selectionCount()>8?'disabled':''} title="整合每批需選取 2～8 份文件">整合選取（2～8份）</button><button class="small" data-action="batch-mark">批次標記</button><button class="small" data-action="clear-selection">取消選取</button></div>${selectionCount()>8?'<span class="help">整合每批最多 8 份；目前仍可批次標記。</span>':''}</div>`:''}<div class="page-top">${controls}</div>${docs.map(d=>`<div class="file-row ${selected?.id===d.id?'selected':''}"><label class="selection-hit"><input type="checkbox" data-select="${e(d.id)}" ${isSelected(d.id)?'checked':''} aria-label="選取 ${e(d.title)}"></label><button class="file-open" data-action="select-doc" data-id="${e(d.id)}"><span class="row space"><span class="file-name">${e(d.path.split(/[\\/]/).at(-1))}</span>${badge(d.effectiveStatus||'active',d.effectiveStatus==='pending_delete'?'amber':'')}</span><span class="file-path">${e(d.relativePath)}</span><span class="row">${badge(d.category)}${d.completed?badge('工作已完成'):''}${d.mark?.stale?badge('標註已過時','red'):''}${d.observedState!=='ok'?badge('來源讀取失敗','red'):''}</span></button></div>`).join('')||empty(state.roots.length?'沒有符合的文件；可調整搜尋條件或索引新增與變更':'先加入要管理的資料夾')}<div class="list-footer"><span>${data.total?`${(filePage-1)*pageSize+1}–${Math.min(filePage*pageSize,data.total)}`:'0'}／${data.total||0} 份 · 只載入摘要</span>${controls}</div></section><aside class="panel">${selected?documentDetail():empty('點文件名稱查看內容；勾選方框可批次操作')}</aside></div>`;
}
async function selectFiltered(){
  if(data.total>2000){selectionSnapshot=await call('selection_snapshot',{rootId:filter.rootId||undefined,query:filter.query,status:filter.status,category:filter.category});snapshotExcluded.clear();checked.clear();await loadView();toast('已固定選取 '+selectionSnapshot.total+' 份符合篩選的文件；批次工作將分段核對來源版本');return;}
  selectionSnapshot=null;snapshotExcluded.clear();

  const query={...filter,cursor:''},found=new Map();let cursor='',expected;
  do{toast(`正在選取搜尋結果，已取得 ${found.size} 份摘要`,'loading');const r=await call('list_documents',{...query,cursor,limit:300});expected??=r.total;if(r.total!==expected||r.total>2000)throw new Error('結果數量已變動或超過 2,000 份，請重新整理後再選取');for(const doc of r.documents)found.set(doc.id,doc);cursor=r.nextCursor;}while(cursor);
  if(found.size!==expected)throw new Error('索引在選取期間已變動，請重新整理後再選取');
  if(JSON.stringify(query)!==JSON.stringify({...filter,cursor:''}))throw new Error('搜尋條件已變動，本次選取未套用，請重新選取');
  const combined=new Map([...checked,...found]);if(combined.size>2000)throw new Error('跨頁選取合計超過 2,000 份，請先取消部分選取');
  checked.clear();for(const [id,doc] of combined)checked.set(id,doc);render();toast(`已選取目前搜尋結果 ${found.size} 份，累計 ${selectionCount()} 份；尚未修改任何文件`);
}
function selectPage(enabled,invert=false){
  if(selectionSnapshot){for(const doc of data.documents||[]){if(!snapshotPageIds.has(doc.id))continue;const remove=invert?!snapshotExcluded.has(doc.id):!enabled;if(remove)snapshotExcluded.add(doc.id);else snapshotExcluded.delete(doc.id);}render();toast('已更新本頁選取，累計 '+selectionCount()+' 份');return;}

  const next=new Map(checked);for(const doc of data.documents||[]){if(invert?next.has(doc.id):!enabled)next.delete(doc.id);else next.set(doc.id,doc);}
  if(next.size>2000)throw new Error('最多同時選取 2,000 份，請先取消部分選取');checked.clear();for(const [id,doc] of next)checked.set(id,doc);render();toast(`已更新本頁選取，累計 ${selectionCount()} 份；尚未修改任何文件`);
}

function documentDetail(){const d=selected,m=d.mark;let body;
  if(docTab==='source')body=renderMarkdown(d.content);if(docTab==='raw')body='<pre class="preview">'+e(d.content)+'</pre>';
  if(docTab==='edit')body=`<form class="form" data-form="edit-document"><label>方案名稱<input name="title" value="編輯 ${e(d.title)}" required></label><label>完整 Markdown<textarea name="content" class="editor" spellcheck="false" data-draft="${e(d.id)}">${e(d.content)}</textarea></label><button class="primary">預覽修改</button></form>`;
  if(docTab==='tools')body='<div class="stack"><button data-action="v3-metadata">編輯用途與中繼資料</button><button data-action="v3-split">路由器＋附件拆分</button><button data-action="v3-replace">搜尋取代目前文件／選取</button></div>';
  if(docTab==='links')body=`<div class="notice">只涵蓋已索引的支援語法與範圍。刪除前會重新索引並核對。</div><button data-action="load-links">讀取入站引用</button><div id="links-result"></div>`;
  if(docTab==='sections')body=`<button data-action="load-sections">列出章節</button><div id="sections-result"></div>`;
  if(docTab==='note')body=`<dl class="kv"><dt>來源版本</dt><dd class="mono">${e(d.hash.slice(0,16))}</dd><dt>分類</dt><dd>${e(d.category)}</dd></dl><form class="form" data-form="mark"><div class="two"><label>狀態<select name="status">${options(['active','completed','pending_delete','keep'],m?.status||'active')}</select></label><label>分類<select name="category">${options([['auto','自動判斷'],...['代理指令','Skill','規格與企劃','使用與操作','任務待辦','驗證與量測','版本與紀錄','授權與署名','其他文件']],d.classification&&!d.classification.stale?d.category:'auto')}</select></label></div><label>理由<textarea name="reason" required>${e(m?.reason||'')}</textarea></label><label>完成／取代依據<textarea name="evidence">${e(m?.evidence||'')}</textarea></label><label class="check"><input type="checkbox" name="completed" ${(m&&!m.stale?m.completed:d.completed)?'checked':''}>已確認工作完成</label><label class="check"><input type="checkbox" name="confirmed" ${m?.confirmed&&!m.stale?'checked':''}>已核對這項標註與保留用途</label><button class="primary">儲存標註</button></form><p class="help" style="margin-top:12px">旁註不改寫原文。完成、待刪除與實際刪除分開處理。</p>${m?.status==='pending_delete'?'<button class="danger" data-action="delete-plan">產生回收方案</button>':''}`;
  return `<div class="body"><div class="row space"><span class="row">${badge(d.effectiveStatus||'active',m?.status==='pending_delete'?'amber':'')}${d.managed||d.protectedFile||d.hardlinked?badge('受保護來源','red'):''}</span><button class="small" data-action="move-document" ${d.managed||d.protectedFile||d.hardlinked?'disabled':''}>移動／改名</button></div><h2 style="margin-top:10px">${e(d.title)}</h2><div class="mono muted">${e(d.path)}</div></div><div class="tabs">${[['note','標註'],['source','閱讀'],['raw','原始碼'],['sections','章節'],['edit','編輯'],['links','引用'],['tools','整理工具']].map(([id,name])=>`<button data-action="doc-tab" data-tab="${id}" class="${docTab===id?'active':''}">${name}</button>`).join('')}</div><div class="body">${body}</div>`;}
function findingsPage(){return `<section class="panel"><div class="panel-head"><h2>有依據的整理候選</h2><button data-action="audit-refresh">重新分析</button></div><div class="toolbar"><select id="finding-state">${options(['open','accepted','dismissed','snoozed','resolved','stale'],findingFilter.state)}</select><select id="finding-rule">${options([['','所有規則'],['description','用途與觸發'],['routing','流程拆分'],['always','固定閱讀／測試'],['authorization','授權'],['overlap','完全重複'],['similar','字詞近似'],['link','失效引用']],findingFilter.rule)}</select></div><div class="notice" style="margin:15px">規則命中是候選，不代表指令有錯。AI 審核需留下原文、理由與版本。</div>${(data.findings||[]).map(f=>`<article class="entry"><div class="row space">${badge(f.rule,'blue')}${badge(f.state)}</div><h3>${e(f.title)} · 第 ${f.line} 行</h3><div class="mono muted">${e(f.path)}</div><pre class="preview">${e(f.original)}</pre><p>${e(f.suggestion)}</p>${f.reviewReason?`<p class="help">上次處置：${e(f.reviewReason)}</p>`:''}<div class="row"><button class="small" data-action="finding-source" data-id="${e(f.documentId)}">查看來源</button><button class="small" data-action="finding-review" data-id="${e(f.id)}" data-state="accepted">採用建議</button><button class="small" data-action="finding-review" data-id="${e(f.id)}" data-state="dismissed">忽略並記錄理由</button></div></article>`).join('')||empty('目前沒有此類待處理建議')}<div class="list-footer"><span>${data.total||0} 項 · 每頁50項</span><button data-action="next-findings" ${data.nextCursor?'':'disabled'}>下一頁</button></div></section>`;}
function historyPage(){const rows=data.items||[],controls='<div class="list-footer"><span>'+data.total+' 批</span><div class="row"><button data-action="history-page" data-offset="'+Math.max(0,historyOffset-30)+'" '+(!historyOffset?'disabled':'')+'>上一頁</button><button data-action="history-page" data-offset="'+(historyOffset+30)+'" '+(!data.hasMore?'disabled':'')+'>下一頁</button></div></div>';return '<section class="panel"><div class="panel-head"><h2>可搜尋與還原的變更批次</h2><input id="history-query" type="search" aria-label="搜尋變更歷史" placeholder="搜尋批次名稱" value="'+e(historyQuery)+'"></div>'+rows.filter(p=>page!=='trash'||['applied','recovery_required','applying','failed'].includes(p.status)).map(p=>'<article class="entry"><h3>'+e(p.title)+'</h3>'+badge(p.status)+'<p>'+p.operations+' 項 · '+e(p.at)+'</p>'+(p.kind==='maintenanceEvent'?'<p>政策維護；請在對應方案中還原。</p>':'<button data-action="plan" data-id="'+e(p.id)+'" data-kind="'+e(p.kind)+'">查看差異與還原</button>')+'</article>').join('')+controls+'</section>';}
function knowledgePage(){return `<div class="workspace"><section class="panel"><div class="panel-head"><h2>知識卡 <span class="muted">${data.total||0}</span></h2><button data-action="v3-export-knowledge">匯出20筆</button><button data-action="v3-import-knowledge">匯入資料包</button><button data-action="knowledge-search">按本次需求檢索</button></div><div class="toolbar"><input type="search" id="knowledge-query" aria-label="搜尋經驗" placeholder="名稱或內容關鍵字" value="${e(knowledgeFilter.query)}"><select id="knowledge-review">${options([['','所有可靠程度'],'candidate','validated','needs_review','rejected'],knowledgeFilter.review)}</select><select id="knowledge-lifecycle">${options(['active','archived','pending_delete','trashed'],knowledgeFilter.lifecycle)}</select></div>${(data.items||[]).map(k=>`<button class="file-open entry" style="width:100%" data-action="select-knowledge" data-id="${e(k.id)}"><div class="row space"><span class="file-name">${e(k.title)}</span>${badge(k.reviewState,k.reviewState==='validated'?'green':'amber')}</div><p class="help">${e(k.summary||'')}<br>${e(types[k.type]||k.type)} · r${k.revision} · ${e(k.domains?.join('、')||'未指定領域')}</p></button>`).join('')||empty('新增一筆有來源及適用情境的經驗')}<div class="list-footer"><span>摘要列表，正文按需讀取</span><button data-action="next-knowledge" ${data.nextCursor?'':'disabled'}>下一頁</button></div></section><aside class="panel">${selectedKnowledge?knowledgeDetail():empty('選擇知識卡查看正文與維護動作')}</aside></div>`;}
function knowledgeDetail(){const k=selectedKnowledge;return `<div class="body"><div class="row">${badge(k.reviewState,k.reviewState==='validated'?'green':'amber')}${badge(k.lifecycle)}${badge(`r${k.revision}`)}</div><h2 style="margin-top:13px">${e(k.title)}</h2><p style="white-space:pre-wrap">${e(k.content)}</p><dl class="kv"><dt>來源</dt><dd>${e(k.source)}</dd><dt>何時適用</dt><dd>${e(k.appliesWhen)}</dd><dt>不適用</dt><dd>${e(k.notWhen||'未指定')}</dd><dt>明確條件</dt><dd>${e(JSON.stringify(k.appliesTo||{}))}</dd><dt>確認依據</dt><dd>${e(k.evidence||'尚未確認')}</dd></dl><div class="notice">修改內容、條件或來源後，原有確認會降為需複核；舊證據保留於歷史。</div><div class="row"><button data-action="edit-knowledge">編輯</button><button data-action="knowledge-history">修訂歷史</button>${k.lifecycle==='trashed'?'<button data-action="knowledge-state" data-state="active">還原</button>':`<button data-action="knowledge-state" data-state="pending_delete">待刪除</button><button data-action="knowledge-state" data-state="archived">封存</button><button class="danger" data-action="knowledge-state" data-state="trashed">移入回收區</button>`}</div></div>`;}
function tasksPage(){return `<div class="workspace"><section class="panel"><div class="panel-head"><h2>任務摘要</h2><button data-action="new-task">新增任務</button></div>${(data.tasks||[]).map(t=>`<button class="file-open entry" style="width:100%" data-action="select-task" data-id="${e(t.id)}"><div class="row space"><strong>${e(t.title)}</strong>${badge(t.status)}</div><p class="help">${e(t.goal)} · r${t.revision}</p></button>`).join('')||empty('新增任務，記錄目的與可觀察的完成條件')}</section><aside class="panel">${task?taskDetail():empty('選擇任務，查看未知、方法與驗收')}</aside></div>`;}
function taskDetail(){return `<div class="body"><div class="row space">${badge(task.status)}${badge(`需求 r${task.revision}`)}</div><h2 style="margin-top:13px">${e(task.title)}</h2><p>${e(task.goal)}</p><h3>限制與交付物</h3><ul>${[...(task.constraints||[]),...(task.deliverables||[])].map(v=>`<li>${e(v)}</li>`).join('')}</ul><h3>未知與假設</h3><ul>${[...(task.unknowns||[]),...(task.assumptions||[])].map(v=>`<li>${e(typeof v==='string'?v:v.text)}</li>`).join('')||'<li class="muted">尚未記錄</li>'}</ul><div class="row"><button data-action="edit-task">修正理解</button><button data-action="task-methods">選用方法</button><button data-action="evidence">記錄證據</button><button data-action="task-report">成果回報</button></div><h3 style="margin-top:20px">完成條件</h3>${task.criteria.map(c=>`<form class="criterion form" data-form="criterion" data-id="${e(c.id)}"><strong>${e(c.text)}</strong><div class="row"><select name="criterionStatus">${options(['pending','passed','failed','unverified'],c.status)}</select><span class="help">通過/未通過須有證據</span></div><textarea name="evidence" placeholder="實際觀察或結果位置">${e(c.evidence||'')}</textarea><button class="small">儲存檢查</button></form>`).join('')}<button class="primary" style="margin-top:15px" data-action="complete-task">標記任務完成</button></div>`;}
function domainsPage(){return `<section class="panel"><div class="panel-head"><h2>薄領域包：來源、版本與真實陷阱</h2><button data-action="new-domain">新增領域包</button></div>${(data.items||[]).map(d=>`<article class="entry"><div class="row space"><h3>${e(d.title)}</h3>${badge(d.version)}</div><p>${e(d.appliesWhen)}</p><div class="mono">${e(d.source)}</div><p class="help">${e(d.gotchas)}</p><button data-action="edit-domain" data-id="${e(d.id)}">編輯來源</button></article>`).join('')||empty('先整理能改變決策的來源與版本，不需要複製整本手冊')}</section>`;}
function reportPage(){if(!task)return empty('先在「本次任務」選擇任務');const r=data;return `<section class="panel"><div class="panel-head"><h2>${e(task.title)}</h2>${badge(`需求 r${r.taskRevision}`)}</div><div class="body"><div class="notice good">${r.evaluation?.representative.passed||0} / ${r.evaluation?.representative.total||0} 項通過 · ${task.status==='completed'?'任務已完成':'任務仍未完成'}</div><dl class="kv"><dt>應用階段</dt><dd>${e(r.applicationLevel)}</dd><dt>基準比較</dt><dd>未量測</dd><dt>遷移測試</dt><dd>未量測</dd></dl><h3>仍有缺口</h3><ul>${(r.remainingGaps||[]).map(v=>`<li>${e(v)}</li>`).join('')||'<li>目前條件已通過；來源與測量範圍仍需一起判讀。</li>'}</ul><h3>此版本的證據</h3>${(r.evidence||[]).map(ev=>`<p>${badge(ev.outcome)} <span class="mono">${e(ev.artifactRef)}</span></p>`).join('')||'<p class="muted">尚未掛接獨立證據紀錄。</p>'}<p class="help">${e(r.note)}</p><button data-action="copy-report">複製結構化回報</button></div></section>`;}
function scopesPage(){return `<section class="panel"><div class="panel-head"><h2>已加入範圍</h2><button data-action="new-scope">加入資料夾</button></div>${state.roots.map(r=>`<article class="entry"><div class="row space"><h3>${e(r.name)}</h3>${badge(r.includeManaged?'包含上游只讀文件':'專案文件')}</div><div class="mono">${e(r.path)}</div><div class="row" style="margin-top:12px">${mode==='md'?`<button data-action="watch" data-id="${e(r.id)}" data-enabled="${state.overview.watching?.includes(r.id)?'false':'true'}">${state.overview.watching?.includes(r.id)?'停止監看':'此服務啟用監看'}</button>`:''}<button class="danger" data-action="remove-scope" data-id="${e(r.id)}">移除管理範圍</button></div></article>`).join('')||empty('只有加入的資料夾會被索引；原始檔案不需搬動')}<div class="body help">監看僅在此服務運行時有效；手動索引可對帳漏事件。父子範圍共用文件索引。</div></section>`;}
function visualPage(){return `<div class="stack"><section class="panel"><div class="panel-head"><h2>主動加入的視覺素材</h2><input type="file" id="asset-upload" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm" multiple aria-label="加入參考圖片"></div><div class="body asset-grid">${(data.assets||[]).slice(0,30).map(a=>`<article>${a.mime?.startsWith('video/')?'<video controls preload="metadata" data-asset="'+e(a.id)+'"></video>':'<img data-asset="'+e(a.id)+'" alt="'+e(a.name)+'">'}<p>${e(a.name)}</p></article>`).join('')||empty('PNG／JPEG／WebP／MP4／WebM，每份最多8MiB；影片最多60秒')}</div></section><section class="panel"><div class="panel-head"><h2>畫面比較與情境偏好</h2></div><div class="body"><form class="form" data-form="comparison"><label>比較名稱<input name="title" required></label><div class="two"><label>左圖<select name="leftAssetId" required>${options((data.assets||[]).map(a=>[a.id,a.name]))}</select></label><label>右圖<select name="rightAssetId" required>${options((data.assets||[]).map(a=>[a.id,a.name]))}</select></label></div><label>選擇<select name="preferred">${options([['neither','尚未決定'],['left','偏好左圖'],['right','偏好右圖']])}</select></label><label>理由與適用範圍<textarea name="notes" required></textarea></label><button class="primary">保存比較</button></form></div></section>${(data.comparisons||[]).slice(0,20).map(c=>`<section class="panel body"><h3>${e(c.title)}</h3><div class="two"><img class="compare-image" data-asset="${e(c.leftAssetId)}" alt="比較左圖"><img class="compare-image" data-asset="${e(c.rightAssetId)}" alt="比較右圖"></div><p>${e(c.notes.join('\n'))}</p><p class="help">${e(c.preferred)} · 不自動變成跨專案規則</p></section>`).join('')}</div>`;}
async function hydrateImages(){const active=new Set([...document.querySelectorAll('[data-asset]')].map(el=>el.dataset.asset));for(const[id,url]of imageUrls)if(!active.has(id)){URL.revokeObjectURL(url);imageUrls.delete(id);}for(const img of document.querySelectorAll('img[data-asset],video[data-asset]')){const id=img.dataset.asset;if(!imageUrls.has(id)){const res=await fetch(`/api/asset/${encodeURIComponent(id)}`,{headers:{'x-workbench-token':token}});if(res.ok)imageUrls.set(id,URL.createObjectURL(await res.blob()));}if(imageUrls.has(id))img.src=imageUrls.get(id);}}

function scopeDialog(){openDialog('加入管理範圍',`<form id="scope-form" class="form" data-form="scope"><label>完整資料夾路徑<input name="path" required placeholder="D:\\AI\\專案\\網站"></label><label>名稱<input name="name"></label><label class="check"><input type="checkbox" name="includeManaged">連套件/上游 MD 一起盤點（仍只讀）</label></form>`,'<button class="primary" form="scope-form">加入資料夾</button>');}
function knowledgeDialog(k=null){openDialog(k?'編輯知識卡':'新增知識卡',`<form id="knowledge-form" class="form" data-form="knowledge" data-id="${e(k?.id||'')}"><div class="two"><label>名稱<input name="title" value="${e(k?.title||'')}" required></label><label>類型<select name="type">${options(Object.entries(types),k?.type||'method')}</select></label></div><label>內容<textarea name="content" required>${e(k?.content||'')}</textarea></label><div class="two"><label>範圍<select name="scope">${rootOptions(k?.scope||filter.rootId||'personal',true)}</select></label><label>可靠程度<select name="reviewState">${options(['candidate','validated','needs_review','rejected'],k?.reviewState||'candidate')}</select></label></div><label>來源<input name="source" value="${e(k?.source||'')}" required></label><label>何時適用<textarea name="appliesWhen" required>${e(k?.appliesWhen||'')}</textarea></label><label>不適用情境<textarea name="notWhen">${e(k?.notWhen||'')}</textarea></label><div class="two"><label>領域（逗號分隔）<input name="domains" value="${e(k?.domains?.join(',')||'')}"></label><label>失效日期<input type="date" name="expiresAt" value="${e(k?.expiresAt?.slice(0,10)||'')}"></label></div><div class="two"><label>平台精確條件<input name="platform" value="${e(k?.appliesTo?.platform||'')}"></label><label>技術精確版本<input name="version" value="${e(k?.appliesTo?.version||'')}"></label></div><label>確認依據<textarea name="evidence">${e(k?.evidence||'')}</textarea></label></form>`,'<button class="primary" form="knowledge-form">保存知識卡</button>');}
function taskDialog(t=null){openDialog(t?'修正理解':'新增需求摘要',`<form id="task-form" class="form" data-form="task"><label>名稱<input name="title" value="${e(t?.title||'')}" required></label><label>目的<textarea name="goal" required>${e(t?.goal||'')}</textarea></label><label>範圍<select name="scope" ${t?'disabled':''}>${rootOptions(t?.scope||filter.rootId||'personal',true)}</select></label>${[['constraints','限制'],['deliverables','交付物'],['criteria','完成條件'],['unknowns','關鍵未知'],['assumptions','暫定假設']].map(([key,label])=>`<label>${label}（每行一項）<textarea name="${key}" ${key==='criteria'?'required':''}>${e((t?.[key]||[]).map(v=>typeof v==='string'?v:v.text).join('\n'))}</textarea></label>`).join('')}<div class="two"><label>平台<input name="platform" value="${e(t?.environment?.platform||'')}"></label><label>技術版本<input name="version" value="${e(t?.environment?.version||'')}"></label></div>${t?'<label>本次修正理由<input name="correction" required></label>':''}</form>`,'<button class="primary" form="task-form">保存摘要</button>');}
function domainDialog(d=null){editingDomain=d;openDialog(d?'編輯領域來源':'新增薄領域包',`<form id="domain-form" class="form" data-form="domain" data-id="${e(d?.id||'')}"><label>名稱<input name="title" value="${e(d?.title||'')}" required></label><label>適用技術版本<input name="version" value="${e(d?.version||'')}" required></label><label>官方/專案來源（每行一項）<textarea name="source" required>${e(d?.source||'')}</textarea></label><label>何時使用<textarea name="appliesWhen">${e(d?.appliesWhen||'')}</textarea></label><label>已知陷阱與待查缺口<textarea name="gotchas">${e(d?.gotchas||'')}</textarea></label></form>`,'<button class="primary" form="domain-form">保存領域包</button>');}
async function planDialog(id,kind='plan',index=0,offset=0){
  const p=await call(kind==='knowledgePlan'?'read_knowledge_change':'read_change_plan',{id,operationIndex:index,offset});
  const selectedOp=p.selectedOperation,show=value=>typeof value==='object'&&value!==null?JSON.stringify(value,null,2):value;
  const body=`<p class="help">逐項、逐段查看差異；來源較長時可繼續讀下一段。第 ${index+1}/${p.operations.length} 項 · 字元 ${offset} 起</p><div class="mono">${e(selectedOp?.path||'')}</div><div class="diff"><div><h3>修改前</h3><pre class="preview">${e(show(selectedOp?.before)??'（新資料）')}</pre></div><div><h3>修改後</h3><pre class="preview">${e(show(selectedOp?.after)??'（移除來源，可還原）')}</pre></div></div><div class="row"><button data-action="plan" data-id="${e(id)}" data-kind="${kind}" data-index="${Math.max(0,index-1)}" ${index?'':'disabled'}>上一項</button><button data-action="plan" data-id="${e(id)}" data-kind="${kind}" data-index="${index+1}" ${index+1<p.operations.length?'':'disabled'}>下一項</button><button data-action="plan" data-id="${e(id)}" data-kind="${kind}" data-index="${index}" data-offset="0" ${offset?'':'disabled'}>此項開頭</button><button data-action="plan" data-id="${e(id)}" data-kind="${kind}" data-index="${index}" data-offset="${selectedOp?.nextOffset||0}" ${selectedOp?.nextOffset?'':'disabled'}>下一段內容</button></div>`;
  openDialog(p.title,`${badge(p.status)}<div style="margin-top:12px">${body}</div>`,p.status==='proposed'?`<button class="primary" data-action="apply-plan" data-id="${e(id)}" data-kind="${kind}">確認套用這批變更</button>`:['applied','applying','recovery_required','failed'].includes(p.status)?`<button class="danger" data-action="restore-plan" data-id="${e(id)}" data-kind="${kind}">還原這批變更</button>`:'');
  if(p.status==='proposed')dialogContent.querySelector('.dialog-foot').insertAdjacentHTML('afterbegin','<button data-action="v3-apply-policy" data-id="'+e(id)+'" data-kind="'+e(kind)+'">依既有授權政策套用</button>');
}
let mergeDocs=[],mergeClauses=new Map();
async function mergeDialog(){
  if(selectionCount()<2||selectionCount()>8)throw new Error('每批選取2–8份');
  mergeDocs=await Promise.all([...checked.keys()].map(documentId=>api('/api/document',{documentId})));
  mergeClauses.clear();for(const d of mergeDocs){const result=await call('review_document',{action:'clauses',documentId:d.id});mergeClauses.set(d.id,result.clauses);}
  const target=mergeDocs[0];
  const body='<form id="merge-form" class="form" data-form="merge"><label>保留的目標文件<select name="targetId">'+options(mergeDocs.map(d=>[d.id,d.relativePath]),target.id)+'</select></label><label>方案名稱<input name="title" value="整合 '+mergeDocs.length+' 份文件" required></label><div class="notice">有效內容需保留；未保留的區塊必須逐條記錄取代或捨棄理由。來源本輪仍保留。</div><label>整合後完整 Markdown<textarea name="content" class="editor" data-merge-draft>'+e(target.content)+'</textarea></label>'+mergeDocs.map(d=>'<details><summary>'+e(d.relativePath)+' 的來源與逐段去向</summary><pre class="preview" data-merge-source>'+e(d.content)+'</pre>'+(mergeClauses.get(d.id)||[]).map(c=>'<fieldset><legend>區塊 '+(c.index+1)+'</legend><p>'+e(c.text.slice(0,350))+'</p><label>處理方式<select name="resolution:'+c.id+'">'+options([['retained','保留原文（會自動核對）'],['replaced','以新內容取代'],['discarded','明確捨棄']])+'</select></label><label>新成果中的對應文字<textarea name="target:'+c.id+'"></textarea></label><label>取代／捨棄理由<input name="reason:'+c.id+'"></label></fieldset>').join('')+'</details><label>'+e(d.relativePath)+' 的整體處理說明<input name="coverage:'+e(d.id)+'" required></label>').join('')+'</form>';
  openDialog('整合文件：保留內容與去向',body,'<button class="primary" form="merge-form">預覽整合方案</button>');
}

