  if(name==='remove-scope')openDialog('移除管理範圍',`<p>只移除索引關係；原始檔案不會刪除，仍屬於其他範圍的文件會保留。</p>`,`<button class="danger" data-action="remove-scope-confirm" data-id="${e(el.dataset.id)}">移除此範圍</button>`);
