const lines=v=>String(v||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);
async function submit(form){if(await nextUI.submit(form))return;const v=Object.fromEntries(new FormData(form)),kind=form.dataset.form;
  if(kind==='jump-page'){const max=Math.max(1,Math.ceil(data.total/pageSize)),n=Number(v.page);if(!Number.isInteger(n)||n<1||n>max)throw new Error(`請輸入 1～${max} 的頁碼`);filePage=n;await loadView();toast(`已前往第 ${filePage} 頁`);return;}
  if(kind==='scope'){await call('add_scope',{...v,includeManaged:v.includeManaged==='on'});closeDialog();await refresh();toast('已加入管理範圍，請執行「索引新增與變更」載入文件');}
  if(kind==='mark'){await call('annotate_document',{documentId:selected.id,expectedHash:selected.hash,status:v.status,reason:v.reason,evidence:v.evidence,completed:v.completed==='on',confirmed:v.confirmed==='on',category:v.category});selected=await api('/api/document',{documentId:selected.id});await refresh();toast('已保存標註，原文保留');}
  if(kind==='edit-document'){const p=await call('create_change_plan',{title:v.title,operations:[{type:'write',documentId:selected.id,expectedHash:selected.hash,content:v.content}]});await planDialog(p.id);}
  if(kind==='new-file'){const p=await call('create_change_plan',{title:`新增 ${v.relativePath}`,operations:[{type:'create',rootId:v.rootId,relativePath:v.relativePath,content:v.content}]});await planDialog(p.id);}
  if(kind==='move-file'){await call('scan_markdown');const p=await call('create_move_plan',{documentId:selected.id,expectedHash:selected.hash,rootId:v.rootId,relativePath:v.relativePath});await planDialog(p.id);}
  if(kind==='merge'){const target=mergeDocs.find(d=>d.id===v.targetId),coverage=mergeDocs.map(d=>({documentId:d.id,hash:d.hash,disposition:v['coverage:'+d.id],clauses:(mergeClauses.get(d.id)||[]).filter(c=>v['resolution:'+c.id]!=='retained').map(c=>({id:c.id,resolution:v['resolution:'+c.id],target:v['target:'+c.id],reason:v['reason:'+c.id]}))}));const p=await call('create_change_plan',{title:v.title,sourceDocuments:mergeDocs.map(d=>({documentId:d.id,expectedHash:d.hash})),operations:[{type:'write',documentId:target.id,expectedHash:target.hash,content:v.content}]});await api('/api/merge-coverage',{id:p.id,coverage});await planDialog(p.id);}
  if(kind==='batch-mark'&&selectionSnapshot){job=await call('background_job',{action:'start',values:{action:'batch_mark',selectionId:selectionSnapshot.id,excludeIds:[...snapshotExcluded],status:v.status,reason:v.reason,evidence:v.evidence}});closeDialog();render();pollJob();toast('批次標記工作已開始，可追蹤、取消或恢復');return;}
  if(kind==='batch-mark'){toast(`正在標記 ${selectionCount()} 份文件，請稍候`,'loading');await api('/api/batch-mark',{documents:[...checked.values()].map(d=>({id:d.id,hash:d.hash})),status:v.status,reason:v.reason,evidence:v.evidence});closeDialog();await refresh();toast(`已將 ${selectionCount()} 份標記為「${names[v.status]||v.status}」，原文未改動；待刪除仍需完成依據核對`);}
  if(kind==='review'){const f=data.findings.find(f=>f.id===form.dataset.id);await call('review_finding',{id:f.id,state:form.dataset.state,reason:v.reason,expectedHash:f.sourceHash,origin:'human'});closeDialog();await loadView();toast('已保存審核處置；採用建議不會自動改寫來源');}
  if(kind==='knowledge'){const k=form.dataset.id?selectedKnowledge:null;const payload={title:v.title,content:v.content,type:v.type,scope:v.scope,reviewState:v.reviewState,source:v.source,appliesWhen:v.appliesWhen,notWhen:v.notWhen,evidence:v.evidence,domains:v.domains.split(/[,，]/).map(s=>s.trim()).filter(Boolean),expiresAt:v.expiresAt?new Date(`${v.expiresAt}T23:59:59`).toISOString():'',appliesTo:Object.fromEntries(['platform','version'].filter(x=>v[x]).map(x=>[x,v[x]])),...(k?{id:k.id,expectedRevision:k.revision}:{})};selectedKnowledge=await call('save_experience',payload);closeDialog();page='knowledge';await refresh();toast(selectedKnowledge.reviewState==='needs_review'?'已保存新版本，需要重新核對':'已保存知識卡');}
  if(kind==='knowledge-state'){selectedKnowledge=await call('set_knowledge_state',{id:selectedKnowledge.id,expectedRevision:selectedKnowledge.revision,lifecycle:form.dataset.state,reason:v.reason,confirm:true});closeDialog();await refresh();toast(`知識卡已${names[selectedKnowledge.lifecycle]||selectedKnowledge.lifecycle}，可查閱修訂歷史`);}
  if(kind==='search-knowledge'){const r=await call('search_knowledge',{query:v.query,domain:v.domain||undefined,scope:filter.rootId||task?.scope||'personal',environment:task?.environment||{},limit:6});openDialog('本次檢索摘要',`<h3>可供判讀的結果 ${r.items?.length||0} 筆</h3>${(r.items||[]).map(k=>`<article class="entry"><strong>${e(k.title)}</strong><p>${e(k.summary)}</p><p class="help">${e(k.selectedBecause)}</p></article>`).join('')||empty('沒有適用結果，請補來源或明確條件')}<h3 style="margin-top:18px">待核對候選（未加入已選用內容）</h3>${(r.uncertain||[]).map(k=>`<p>${e(k.title)} · ${badge('需核對適用條件','amber')}</p>`).join('')||'<p class="help">無</p>'}`);}
  if(kind==='task'){const payload={title:v.title,goal:v.goal,constraints:lines(v.constraints),deliverables:lines(v.deliverables),criteria:lines(v.criteria),unknowns:lines(v.unknowns),assumptions:lines(v.assumptions),environment:Object.fromEntries(['platform','version'].filter(k=>v[k]).map(k=>[k,v[k]])),...(task&&form.querySelector('[name=correction]')?{id:task.id,expectedRevision:task.revision,correction:v.correction}:{scope:v.scope})};task=payload.id?await api('/api/task',payload):(await call('compile_task_request',{...payload,request:v.request||v.goal})).task;page='tasks';taskCursor='';await refresh();closeDialog();toast(`任務摘要已保存（第 ${task.revision} 版）`);}
  if(kind==='criterion'){task=await call('update_task_brief',{id:task.id,expectedRevision:task.revision,criterionId:form.dataset.id,criterionStatus:v.criterionStatus,evidence:v.evidence});await refresh();toast(`驗收檢查已保存：${names[v.criterionStatus]||v.criterionStatus}`);}
  if(kind==='methods'){task=await api('/api/task',{id:task.id,expectedRevision:task.revision,methods:new FormData(form).getAll('methods')});closeDialog();await refresh();toast(`已保存本次選用的 ${task.methods?.length||0} 種方法`);}
  if(kind==='evidence'){await call('record_evidence',{...v,taskId:task.id,taskRevision:task.revision,environment:task.environment||{}});closeDialog();toast('已保存此版本的證據紀錄');}
  if(kind==='domain'){await api('/api/save-domain',{...v,...(editingDomain?{id:editingDomain.id,expectedRevision:editingDomain.revision||0,scope:editingDomain.scope}:{scope:filter.rootId||'personal'})});domainCursor='';closeDialog();page='domains';await loadView();toast('領域來源已保存新版本；尚未自動查核外部來源');}
  if(kind==='comparison'){await call('save_visual_comparison',{...v,scope:filter.rootId||'personal',notes:lines(v.notes)});await loadView();toast('已保存比較，不自動產生全域偏好');}
}
async function pollJob(){clearTimeout(jobTimer);try{job=await call('get_index_job',{id:job.id});if(['queued','running'].includes(job.status)){const bar=app.querySelector('.jobbar');if(bar)bar.outerHTML=jobBar();else render();jobTimer=setTimeout(pollJob,700);}else{await refresh();toast(job.status==='completed'?(job.action==='batch_mark'?'標記完成：'+job.succeeded+' 份':`索引完成：${job.result.changed} 份變更，${job.result.unchanged} 份未變`):`索引${names[job.status]||job.status}，請查看工作資訊`);}}catch(err){toast(err.message,'error');}}
document.addEventListener('click',ev=>{const el=ev.target.closest('button[data-action]');if(!el||el.disabled)return;if(['close','dismiss-feedback'].includes(el.dataset.action)){action(el.dataset.action,el);return;}runUi(async()=>{const remote=['refresh','scan','select-filtered','apply-plan','restore-plan','audit-refresh','delete-plan','move-document','load-links','load-sections','watch','remove-scope-confirm'];if(remote.includes(el.dataset.action))toast(`正在${el.textContent.trim()}，請稍候`,'loading');await action(el.dataset.action,el);},el);});
document.addEventListener('submit',ev=>{const form=ev.target.closest('form[data-form]');if(form){ev.preventDefault();runUi(async()=>{if(form.dataset.form!=='jump-page')toast('正在處理，請稍候','loading');await submit(form);},ev.submitter);}});
document.addEventListener('input',ev=>{const el=ev.target;nextUI.saveDraft(el.closest('form[data-context]'));if(el.dataset.draft)drafts.set(el.dataset.draft,el.value);if(['document-search','knowledge-query','history-query'].includes(el.id)){const start=el.selectionStart,id=el.id;clearTimeout(searchTimer);searchTimer=setTimeout(()=>perform(async()=>{if(id==='document-search'){filter.query=el.value;filter.cursor='';filePage=1;}else if(id==='history-query'){historyQuery=el.value;historyOffset=0;}else{knowledgeFilter.query=el.value;knowledgeFilter.cursor='';}await loadView();const input=document.getElementById(id);input?.focus();input?.setSelectionRange(start,start);}),280);}});
document.addEventListener('change',ev=>{const el=ev.target;perform(async()=>{
  if(el.id==='select-page'){selectPage(el.checked);return;}
  if(el.id==='page-size'){pageSize=Number(el.value);filePage=1;await loadView();toast(`已改為每頁 ${pageSize} 份，跨頁選取保留`);return;}
  if(el.dataset.select&&selectionSnapshot){if(el.checked)snapshotExcluded.delete(el.dataset.select);else snapshotExcluded.add(el.dataset.select);render();toast('已選取 '+selectionCount()+' 份');return;}
  if(el.dataset.select){if(el.checked&&selectionCount()>=2000){el.checked=false;throw new Error('最多同時選取 2,000 份');}if(el.checked){checked.set(el.dataset.select,data.documents.find(d=>d.id===el.dataset.select));}else checked.delete(el.dataset.select);render();toast(`已選取 ${selectionCount()} 份，尚未修改任何文件`);}
  if(el.id==='root-scope'){selectionSnapshot=null;snapshotExcluded.clear();snapshotPageIds.clear();for(const k of Object.keys(cursorStacks))cursorStacks[k]=[];historyOffset=0;filter.rootId=el.value;filter.cursor='';filePage=1;knowledgeFilter.cursor='';taskCursor='';domainCursor='';task=null;selected=null;selectedKnowledge=null;checked.clear();await loadView();}
  if(el.id==='status-filter'){filter.status=el.value;filter.cursor='';filePage=1;await loadView();}
  if(el.id==='finding-state'||el.id==='finding-rule'){findingFilter[el.id==='finding-state'?'state':'rule']=el.value;findingFilter.cursor='';await loadView();}
  if(el.id==='knowledge-review'||el.id==='knowledge-lifecycle'){knowledgeFilter[el.id==='knowledge-review'?'review':'lifecycle']=el.value;knowledgeFilter.cursor='';await loadView();}
  if(el.name==='targetId'&&el.closest('#merge-form')){const editor=dialogContent.querySelector('[name=content]');const previous=editor.dataset.target||mergeDocs[0].id;drafts.set(`merge:${previous}`,editor.value);editor.value=drafts.get(`merge:${el.value}`)??mergeDocs.find(d=>d.id===el.value).content;editor.dataset.target=el.value;}
  if(el.id==='asset-upload'){await nextUI.importFiles(el.files);return;}
});});
refresh().catch(err=>{app.innerHTML=empty(`無法開啟工作台：${err.message}`);});
